/**
 * Technology signatures. Each entry names one technology and the evidence that
 * proves it, by where the evidence is found:
 *
 *   headers  { name: RegExp }   response header value (any hop of the redirect chain)
 *   cookies  RegExp[]           cookie name set by the site
 *   meta     { name: RegExp }   <meta name=… content=…> (generator, etc.)
 *   html     RegExp[]           page markup, inline scripts included
 *   urls     RegExp[]           URL of a script, stylesheet, iframe, preload or (with --browser) any request
 *   assets   RegExp[]           contents of a fetched script or stylesheet (bundle banners, runtime markers)
 *   globals  string[]           window property path that exists after load (--browser only);
 *                               a string or number value there is taken as the version
 *   npm      string             package name: a CDN URL naming it (/npm/x@1.2.3, unpkg.com/x@1.2.3,
 *                               /ajax/libs/x/1.2.3/) counts as url evidence with that version
 *
 * A pattern's first capture group, when it matches, is the version; for an
 * entry marked ids: true it is an account or container ID (GTM-…, G-…) instead. Wrap a
 * pattern as { re, weak: true } when it can appear without the technology
 * (a CSS class name, a generic word): a technology seen only through weak
 * evidence is reported as "possible", never as detected.
 *
 * notHosts (RegExp) skips the entry on matching hosts, for platforms whose own
 * site sends the same headers as the sites they host.
 *
 * Keep patterns specific. The old bash detector matched /react/ and /ng-/
 * anywhere in the page and reported React and Angular on nearly every site.
 */

const weak = (re) => ({ re, weak: true });

